const cfg = items[0].json || {};
const missing = [];
const REQUIRED = ['niche','groqApiKey','flikiApiKey','slackWebhook','googleSheetId','uploadPostApiKey','youtubeChannelId'];
for (const f of REQUIRED) {
  if (!cfg[f] || String(cfg[f]).includes('PASTE_')) missing.push(f);
}
return [{
  json: {
    ...cfg,
    configOk: missing.length === 0,
    configError: missing.length ? 'MISSING: ' + missing.join(', ') : '',
    runId: cfg.runId || ('run_' + Date.now()),
    startedAt: cfg.startedAt || new Date().toISOString(),
    workflowPackVersion: cfg.workflowPackVersion || 'v23'
  }
}];

const cfg = items[0].json || {};
const missing = [];
const REQUIRED = ['niche','groqApiKey','flikiApiKey','slackWebhook','googleSheetId','uploadPostApiKey','youtubeChannelId'];
for (const f of REQUIRED) {
  if (!cfg[f] || String(cfg[f]).includes('PASTE_')) missing.push(f);
}
return [{
  json: {
    ...cfg,
    configOk: missing.length === 0,
    configError: missing.length ? 'MISSING: ' + missing.join(', ') : '',
    runId: cfg.runId || ('run_' + Date.now()),
    startedAt: cfg.startedAt || new Date().toISOString(),
    workflowPackVersion: cfg.workflowPackVersion || 'v23'
  }
}];

let rows = [];
try {
  rows = $('Weekly Load Past Videos').all().map(i => i.json);
} catch (e) {}

const now = Date.now();
const recent = rows.filter(r => {
  const t = new Date(r.date || r.Date || r.publishedAt || 0).getTime();
  return t && t >= now - 30 * 86400000;
});

const recent14 = recent.filter(r => {
  const t = new Date(r.date || r.Date || r.publishedAt || 0).getTime();
  return t && t >= now - 14 * 86400000;
});

const avg = arr => arr.length ? arr.reduce((a, b) => a + b, 0) / arr.length : 0;
const getNum = (r, keys) => {
  for (const k of keys) {
    const v = Number(r[k]);
    if (Number.isFinite(v) && v !== 0) return v;
  }
  return 0;
};
const hasGoodOffer = r => {
  const url = String(r.oneLinkOfferUrl || r.offerUrl || '');
  return !!url && !url.includes('PASTE_');
};
const normalizeFamily = (title = '', topic = '') => String(topic || title || '')
  .toLowerCase()
  .replace(/['’]/g, '')
  .replace(/\b(best|free|cheap|cheaper|how|to|for|vs|and|the|a|an|is|still|worth|paying|manual|smart|automation|automate|workflow|tool|tools|app|apps|local|business|businesses|service|services|small|ai|software|stack)\b/g, ' ')
  .replace(/[^a-z0-9 ]+/g, ' ')
  .replace(/\s+/g, ' ')
  .trim()
  .split(' ')
  .filter(Boolean)
  .slice(0, 4)
  .join('-') || 'general';

const category = {
  searchDemand: Number(avg(recent14.map(r => getNum(r, ['searchDemandScore', 'searchIntentScore', 'seoScore']))).toFixed(1)) || 0,
  packaging: Number(avg(recent14.map(r => getNum(r, ['packagingScore', 'ctrPrediction', 'thumbCtr']))).toFixed(1)) || 0,
  retention: Number(avg(recent14.map(r => getNum(r, ['realAvgRetention', 'avgRetention', 'openingQualityScore']))).toFixed(1)) || 0,
  audienceQuality: Number(avg(recent14.map(r => getNum(r, ['audienceOwnershipScore', 'buyerIntentScore']))).toFixed(1)) || 0,
  firstDollarSpeed: Number(avg(recent14.map(r => getNum(r, ['firstDollarScore', 'cashCowScore']))).toFixed(1)) || 0,
  monetizationBreadth: Number(avg(recent14.map(r => getNum(r, ['cashCowScore', 'projectedRoi', 'finalBusinessScore']))).toFixed(1)) || 0,
  buyerIntent: Number(avg(recent14.map(r => getNum(r, ['buyerIntentScore']))).toFixed(1)) || 0,
  seriesDepth: Number(avg(recent14.map(r => getNum(r, ['sequelDepthScore', 'followupPotential']))).toFixed(1)) || 0,
  authenticity: Number(avg(recent14.map(r => getNum(r, ['authenticityHeuristic', 'authenticityScore', 'titleTruthScore']))).toFixed(1)) || 0,
  sponsorSafety: Number(avg(recent14.map(r => getNum(r, ['sponsorSafetyScore']))).toFixed(1)) || 0
};

const offerCoverageRate = recent14.length ? recent14.filter(hasGoodOffer).length / recent14.length : 0;
const offerCoverageScore = Number((offerCoverageRate * 10).toFixed(1));

const familyGroups = {};
for (const r of recent14) {
  const key = normalizeFamily(r.title || r.Title || '', r.topic || r.Topic || '');
  if (!familyGroups[key]) familyGroups[key] = [];
  familyGroups[key].push(r);
}
const familyEntries = Object.entries(familyGroups).filter(([, arr]) => arr.length >= 2);
const sequelWinRate = Number((familyEntries.length
  ? familyEntries.filter(([, arr]) => avg(arr.map(x => getNum(x, ['realScore', 'score']))) >= 7.5).length / familyEntries.length
  : 0).toFixed(2));
const sequelWinRateScore = Number((sequelWinRate * 10).toFixed(1));

const recentErrors = recent14.filter(r => /FAILED|ERROR|SKIP|TRUTH_GATE_FAILED/i.test(String(r.status || ''))).length;
const opsSimplicityScore = Math.max(0, Math.min(10, Number((
  8.8
  - (recentErrors * 0.4)
  - (offerCoverageRate < 0.6 ? 1.0 : 0)
  + (familyEntries.length >= 2 ? 0.4 : 0)
).toFixed(1))));

const cashVelocityScore = Math.max(0, Math.min(10, Number((
  (avg(recent14.map(r => getNum(r, ['firstDollarScore']))) * 0.55) +
  (offerCoverageScore * 0.25) +
  (avg(recent14.map(r => getNum(r, ['buyerIntentScore']))) * 0.20)
).toFixed(1))));

const weightedOverall = Number(((
  category.searchDemand * 0.14 +
  category.packaging * 0.11 +
  (Math.min(category.retention, 10)) * 0.11 +
  category.audienceQuality * 0.09 +
  cashVelocityScore * 0.13 +
  category.monetizationBreadth * 0.09 +
  category.buyerIntent * 0.09 +
  Math.max(category.seriesDepth, sequelWinRateScore) * 0.08 +
  category.authenticity * 0.08 +
  category.sponsorSafety * 0.04 +
  offerCoverageScore * 0.02 +
  opsSimplicityScore * 0.02
)).toFixed(1));

const sortedWeak = Object.entries({
  ...category,
  offerCoverage: offerCoverageScore,
  sequelWinRate: sequelWinRateScore,
  opsSimplicity: opsSimplicityScore,
  cashVelocity: cashVelocityScore
}).sort((a, b) => a[1] - b[1]).slice(0, 4);

const strongest = Object.entries({
  ...category,
  offerCoverage: offerCoverageScore,
  sequelWinRate: sequelWinRateScore,
  opsSimplicity: opsSimplicityScore,
  cashVelocity: cashVelocityScore
}).sort((a, b) => b[1] - a[1]).slice(0, 4);

const topFranchises = familyEntries
  .map(([family, arr]) => ({
    family,
    count: arr.length,
    avgScore: Number(avg(arr.map(x => getNum(x, ['realScore', 'score']))).toFixed(1)),
    avgViews: Math.round(avg(arr.map(x => getNum(x, ['views', 'realViews']))))
  }))
  .sort((a, b) => b.avgScore - a.avgScore || b.avgViews - a.avgViews)
  .slice(0, 5);

const easyFixes = [];
if ((category.packaging || 0) < 7.5) easyFixes.push('Tighten titles and keep one clearer thumbnail concept');
if (cashVelocityScore < 7.0) easyFixes.push('Use one stronger offer page and keep one link only');
if (offerCoverageScore < 7.0) easyFixes.push('Set one offer base URL so every winner gets a routed page');
if ((category.authenticity || 0) < 7.5) easyFixes.push('Add one honest downside and one concrete example to every script');
if (sequelWinRateScore < 6.5) easyFixes.push('Turn each winner into beginner, cheaper, and mistakes sequels faster');
if (opsSimplicityScore < 7.2) easyFixes.push('Reduce moving parts and keep one primary CTA');
if (!easyFixes.length) easyFixes.push('Keep the current system and double down on the strongest lane');

return [{
  json: {
    scorecardWindowDays: 30,
    weightedOverall,
    weakestCategories: sortedWeak.map(([k, v]) => `${k}:${v}`),
    strongestCategories: strongest.map(([k, v]) => `${k}:${v}`),
    easyFixes,
    offerCoverageRate: Number((offerCoverageRate * 100).toFixed(1)),
    offerCoverageScore,
    sequelWinRate: Number((sequelWinRate * 100).toFixed(1)),
    sequelWinRateScore,
    opsSimplicityScore,
    cashVelocityScore,
    topFranchises,
    ...category
  }
}];

