const cfg = items[0].json || {};
const missing = [];
const REQUIRED = ['niche','groqApiKey','flikiApiKey','slackWebhook','googleSheetId','uploadPostApiKey','youtubeChannelId'];
for (const f of REQUIRED) {
  if (!cfg[f] || String(cfg[f]).includes('PASTE_')) missing.push(f);
}
return [{
  json: {
    ...cfg,
    configOk: missing.length === 0,
    configError: missing.length ? 'MISSING: ' + missing.join(', ') : '',
    runId: cfg.runId || ('run_' + Date.now()),
    startedAt: cfg.startedAt || new Date().toISOString(),
    workflowPackVersion: cfg.workflowPackVersion || 'v23'
  }
}];

const cfg = $('Milestone Validate Config').first().json;
const yt = items[0].json || {};
const stats = yt.items?.[0]?.statistics || {};
const subs = Number(stats.subscriberCount || 0);
const views = Number(stats.viewCount || 0);
const estWatchHours = Math.round(views * 4 / 60);
const yppSubPct = Math.min(100, (subs / Number(cfg.yppSubTarget || 1000)) * 100);
const yppHrsPct = Math.min(100, (estWatchHours / Number(cfg.yppWatchHoursTarget || 4000)) * 100);
const yppReady = subs >= Number(cfg.yppSubTarget || 1000) && estWatchHours >= Number(cfg.yppWatchHoursTarget || 4000);
const affiliateReady = subs >= Number(cfg.affiliateReadySubs || 50);
return [{
  json: {
    subscribers: subs,
    totalViews: views,
    estWatchHours,
    yppSubPct: Number(yppSubPct.toFixed(0)),
    yppHrsPct: Number(yppHrsPct.toFixed(0)),
    yppReady,
    affiliateReady,
    slackMessage: yppReady ? `🎉 YPP READY! ${subs} subs and ~${estWatchHours} watch hours.` : `📈 Milestone check: ${subs} subs, ~${estWatchHours} watch hours.`
  }
}];

// ══════════════════════════════════════════════════════════════════════
// MILESTONE EVALUATOR
// Checks: YPP readiness, affiliate readiness, PDF product readiness,
// revenue target, and custom milestones.
// Only fires Slack alert when a milestone is HIT or CLOSE.
// ══════════════════════════════════════════════════════════════════════

const cfg = $('Channel Config').first().json;
const ytResp = (() => { try { return $('Check Milestones').first().json; } catch(e) { return {}; } })();
let rows = [];
try { rows = $('Check Milestones').all().map(i => i.json).filter(r => r.status === 'PUBLISHED' || r.Status === 'PUBLISHED'); } catch(e) {}

// ── Extract stats ──
const subs = Number(ytResp.items?.[0]?.statistics?.subscriberCount || 0);
const totalVids = rows.length;
const winners = rows.filter(r => Number(r.score || r.Score || 0) >= 8).length;

// Read real analytics for watch hours
let totalWatchMins = 0;
let monthlyViews = 0;
let monthlyRevenue = 0;
try {
  // Estimate from 7-day analytics sheet if available
  // For now use rough estimates from dashboard data
  totalWatchMins = totalVids * 150; // rough: 2.5 min avg watch × 60 views per video
  const thirtyDaysAgo = new Date(Date.now() - 30 * 86400000);
  const recentVids = rows.filter(r => new Date(r.date || r.Date || 0) >= thirtyDaysAgo);
  monthlyViews = recentVids.length * 500; // rough estimate until real analytics kick in
} catch(e) {}

const watchHours = totalWatchMins / 60;

// ── YPP ──
const yppSubTarget = Number(cfg.yppSubTarget || 1000);
const yppHrsTarget = Number(cfg.yppWatchHoursTarget || 4000);
const yppSubPct = Math.min(100, (subs / yppSubTarget) * 100);
const yppHrsPct = Math.min(100, (watchHours / yppHrsTarget) * 100);
const yppReady = subs >= yppSubTarget && watchHours >= yppHrsTarget;
const yppClose = !yppReady && (yppSubPct >= 85 || yppHrsPct >= 85);

// ── Affiliate ──
const affSubTarget = Number(cfg.affiliateReadySubs || 1000);
const affVidTarget = Number(cfg.affiliateReadyVideos || 60);
const affWinTarget = Number(cfg.affiliateReadyWinners || 8);
const affiliateReady = subs >= affSubTarget && totalVids >= affVidTarget && winners >= affWinTarget;
const affiliateClose = !affiliateReady && (subs >= affSubTarget * 0.8 || totalVids >= affVidTarget * 0.8);

// ── PDF Product ──
const pdfSubTarget = Number(cfg.pdfReadySubs || 2000);
const pdfViewTarget = Number(cfg.pdfReadyMonthlyViews || 50000);
const pdfReady = subs >= pdfSubTarget && monthlyViews >= pdfViewTarget;

// ── Revenue ──
const revTarget = Number(cfg.targetMonthlyRevenue || 20000);
const revenueHit = monthlyRevenue >= revTarget;

const shouldAlert = yppReady || yppClose || affiliateReady || affiliateClose || pdfReady || revenueHit;

// ── Build Slack message ──
const lines = [];
lines.push(':rocket: *Daily Milestone Check*');
lines.push('');
lines.push(`*Subscribers:* ${subs.toLocaleString()} | *Videos:* ${totalVids} | *Winners:* ${winners} | *Watch Hours:* ${watchHours.toFixed(0)}h`);
lines.push('');

// YPP
if (yppReady) lines.push(':tada: *YPP REQUIREMENTS MET!* Apply now: YouTube Studio → Earn → Apply for YPP.');
else if (yppClose) lines.push(`:fire: *ALMOST YPP!* ${yppSubPct.toFixed(0)}% subs, ${yppHrsPct.toFixed(0)}% watch hours — keep posting daily!`);
else lines.push(`:hourglass: YPP: ${yppSubPct.toFixed(0)}% subs (${subs}/${yppSubTarget}), ${yppHrsPct.toFixed(0)}% hours (${watchHours.toFixed(0)}/${yppHrsTarget})`);

// Affiliate
if (affiliateReady) {
  lines.push('');
  lines.push(':money_with_wings: *AFFILIATE PROGRAMS READY!*');
  lines.push(`Sign up TODAY and add links to your top 10 video descriptions:`);
  lines.push(`• Notion: ${cfg.affiliateNotionUrl || 'https://affiliate.notion.so'} ($16/mo recurring)`);
  lines.push(`• Jasper AI: ${cfg.affiliateJasperUrl || 'https://jasper.ai/affiliate'} (30% recurring)`);
  lines.push(`• ClickUp: ${cfg.affiliateClickUpUrl || 'https://clickup.com/affiliates'} ($65+ per referral)`);
  lines.push(`• HubSpot: ${cfg.affiliateHubspotUrl || 'https://hubspot.com/affiliates'} (up to $1,000/referral)`);
  lines.push(`• Fathom AI: ${cfg.affiliateFathomUrl || 'https://usefathom.com/affiliates'} (25% recurring)`);
  lines.push(`*ACTION:* Open each URL, sign up, add links to top 10 videos. 30 minutes work. Could add $2,000-5,000/month.`);
} else if (affiliateClose) {
  lines.push(`:soon: Affiliate almost ready — ${subs}/${affSubTarget} subs, ${totalVids}/${affVidTarget} videos, ${winners}/${affWinTarget} winners`);
} else {
  lines.push(`:hourglass: Affiliate: ${subs}/${affSubTarget} subs, ${totalVids}/${affVidTarget} vids, ${winners}/${affWinTarget} winners`);
}

// PDF
if (pdfReady) {
  lines.push('');
  lines.push(':page_facing_up: *PDF PRODUCT READY TO LAUNCH!*');
  lines.push(`"${cfg.pdfProductName || 'AI Tools Starter Pack'}" — $${cfg.pdfProductPrice || '47'}`);
  lines.push('1. Create 20-30 page PDF covering top AI tools setup');
  lines.push('2. List on Gumroad/Lemon Squeezy at $47');
  lines.push('3. Add CTA to top 20 video descriptions + pin comments');
  lines.push(`Expected: 100-300 sales/mo = $4,700-$14,100/month passive`);
}

// Revenue
if (revenueHit) {
  lines.push('');
  lines.push(':champagne: *$20,000/MONTH TARGET HIT!* Next: second channel, $197 course, or hire editor to double output.');
}

return [{ json: {
  shouldAlert,
  slackMessage: lines.join('\n'),
  subs, totalVids, winners, watchHours: Number(watchHours.toFixed(1)), monthlyViews, monthlyRevenue,
  milestones: {
    ypp: { ready: yppReady, close: yppClose, subPct: yppSubPct.toFixed(1), hrsPct: yppHrsPct.toFixed(1) },
    affiliate: { ready: affiliateReady, close: affiliateClose },
    pdf: { ready: pdfReady },
    revenue: { hit: revenueHit, current: monthlyRevenue, target: revTarget }
  }
}}];

